package com.campusly;
import com.campusly.data.OpportunityRepository; import com.campusly.data.UserRepository; import com.campusly.domain.Opportunity; import com.campusly.domain.UserAccount; import com.campusly.domain.UserRole; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.LocalDate;
@Configuration
public class SeedData {
 @Bean CommandLineRunner seed(OpportunityRepository opportunities,UserRepository users,PasswordEncoder encoder,@Value("${CAMPUSLY_ADMIN_EMAIL:}") String adminEmail,@Value("${CAMPUSLY_ADMIN_PASSWORD:}") String adminPassword,@Value("${CAMPUSLY_ADMIN_NAME:Campusly Admin}") String adminName){return args->{if(opportunities.count()==0){LocalDate d=LocalDate.now();opportunities.save(new Opportunity("Product Design Intern","Figma","Design & collaboration","F","purple","Internship","Work alongside product designers to shape thoughtful, accessible experiences. Contribute to research, prototyping, and design systems.","Figma,UI Design,Prototyping","Design, HCI, or related students · 2027/2028 grads",d.plusDays(30),"Paid · Summer 2027","Remote"));opportunities.save(new Opportunity("Build for Good Hackathon","Northstar Labs","Technology & innovation","NL","green","Hackathon","Build practical tools for a more sustainable campus with mentors and a team of makers.","React,Python,Teamwork","Open to all undergraduate students",d.plusDays(20),"48 hours · Prizes","Innovation Hall"));opportunities.save(new Opportunity("Software Engineering Intern","Stripe","Payments & technology","S","blue","Internship","Help build reliable financial infrastructure while learning from experienced engineers.","Java,APIs,Problem solving","Computer Science students · 2027 grads",d.plusDays(45),"Paid · Summer 2027","Hybrid"));opportunities.save(new Opportunity("UX Research Essentials","Northstar Career Center","Career development","CC","orange","Workshop","Learn to plan interviews, ask better questions, and turn observations into product insights.","Research,Communication,UI Design","Open to all students",d.plusDays(15),"90 minutes · Free","Student Union"));opportunities.save(new Opportunity("Women in Tech Challenge","Adobe","Creative technology","A","pink","Competition","Design and pitch a digital experience that makes learning more inclusive.","UI Design,Figma,Storytelling","Open to all undergraduate students",d.plusDays(35),"Competition · Awards","Online"));opportunities.save(new Opportunity("Cloud Foundations Certificate","Google Cloud","Cloud & infrastructure","G","blue","Certification","Build a practical understanding of cloud infrastructure, security, and deployment.","Cloud,Python,Databases","Open to all students",d.plusDays(60),"Self-paced · Free","Online"));opportunities.save(new Opportunity("Campus Technology Analyst","Deloitte","Consulting & technology","D","green","Placement","Explore how technology can solve complex client challenges through meaningful projects.","Communication,Python,Problem solving","Computer Science or Business · 2027 grads",d.plusDays(25),"Full-time · Graduate","Multiple cities"));opportunities.save(new Opportunity("Open Source Sprint","GitHub Campus","Developer community","GH","purple","Hackathon","Spend a day contributing to open source with maintainers and fellow students.","Git,JavaScript,Teamwork","Open to all undergraduate students",d.plusDays(70),"1 day · Community","Engineering Quad"));}if(!adminEmail.isBlank()&&!adminPassword.isBlank()){UserAccount admin=users.findByEmailIgnoreCase(adminEmail).orElseGet(()->users.save(new UserAccount(adminEmail,adminName,encoder.encode(adminPassword))));if(admin.getRole()!=UserRole.ADMIN){admin.setRole(UserRole.ADMIN);users.save(admin);}}};}
}
